import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildLineup, measureLineup } from '../src/lineup.js';

describe('measureLineup', () => {
  it('union spans x from -2 to 22 within 1e-6', () => {
    const group = buildLineup(); // measured immediately, no render loop
    const box = measureLineup(group);

    expect(box.min.x).toBeCloseTo(-2, 6);
    expect(box.max.x).toBeCloseTo(22, 6);
  });

  it('each car’s own box is centered at its position', () => {
    const group = buildLineup();
    const center = new THREE.Vector3();

    group.children.forEach((car, i) => {
      const b = new THREE.Box3().setFromObject(car);
      b.getCenter(center);
      expect(center.x).toBeCloseTo(i * 10, 6);
      expect(center.y).toBeCloseTo(0.7, 6);
      expect(center.z).toBeCloseTo(0, 6);
    });
  });

  // Repro of the reported symptom: a car at x=10 with a child wheel
  // still measures as if everything sat near the origin.
  it('a car at x=10 with a child wheel does not collapse to the origin', () => {
    const group = buildLineup();
    const car = group.children[1]; // parked at x = 10
    const wheel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.35, 0.35, 0.25, 16),
      undefined
    );
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(1.4, 0, 0); // local offset inside the car body
    car.add(wheel);

    const box = measureLineup(group);
    const center = box.getCenter(new THREE.Vector3());

    // The wheel must pull the car's footprint out around x≈11.4, not stay at 10.
    const carBox = new THREE.Box3().setFromObject(car);
    expect(carBox.min.x).toBeGreaterThan(7.9); // would be ~-2 (origin-collapsed) if buggy

    // Full union still covers all three cars plus wheels.
    expect(box.min.x).toBeCloseTo(-2, 6);
    expect(center.y).toBeCloseTo(0.7, 5);
  });
});

