import { buildLineup, measureLineup } from '../src/lineup.js';

describe('measureLineup', () => {
  it('union spans x from -2 to 22 within 1e-6', () => {
    const group = buildLineup(); // measured immediately after build — no render loop
    const box = measureLineup(group);

    expect(box.min.x).toBeCloseTo(-2, 6);
    expect(box.max.x).toBeCloseTo(22, 6);
    // sanity: y/z extents of the three bodies
    expect(box.min.y).toBeCloseTo(0, 6);
    expect(box.max.y).toBeCloseTo(1.4, 6);
  });

  it('each car’s own box is centered at its position', () => {
    const group = buildLineup();
    const center = new THREE.Vector3();

    group.children.forEach((car, i) => {
      const b = new THREE.Box3().setFromObject(car);
      b.getCenter(center);
      expect(center.x).toBeCloseTo(i * 10, 6);
      expect(center.y).toBeCloseTo(0.7, 6);
      expect(center.z).toBeCloseTo(0, 6);
    });
  });

  // Regression: a child wheel must be included in its car's footprint.
  it('a car at x=10 with a child wheel includes the wheel', () => {
    const group = buildLineup();
    const car = group.children[1]; // parked at x = 10
    const wheel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.35, 0.35, 0.25, 16)
    );
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(1.4, 0, 0); // local offset inside the car body
    car.add(wheel);

    const box = measureLineup(group);

    expect(box.min.x).toBeCloseTo(-2, 6);
    expect(box.max.x).toBeCloseTo(22, 6); // wheel stays within car 1's span
  });

  // THE BUG: measureLineup is called immediately after buildLineup (plus a
  // placement of the showroom root) with no render loop, so world matrices
  // were never updated. Box3.setFromObject reads matrixWorld and reports
  // every car as if it sat near the origin instead of its world position.
  it('reports world-space boxes when the lineup root itself is placed (no render loop)', () => {
    const group = buildLineup();
    group.position.set(1000, 0, 5); // showroom section B; nothing rendered yet

    const box = measureLineup(group);

    // World-space union must follow the placed root: x in [998, 1022].
    expect(box.min.x).toBeCloseTo(998, 6);
    expect(box.max.x).toBeCloseTo(1022, 6);
    expect(box.min.z).toBeCloseTo(4, 6);
    expect(box.max.z).toBeCloseTo(6, 6);

    // First car's own box centered at its WORLD position (1000, 0.7, 5).
    const center = new THREE.Box3().setFromObject(group.children[0]).getCenter(new THREE.Vector3());
    expect(center.x).toBeCloseTo(1000, 6);
    expect(center.y).toBeCloseTo(0.7, 6);
    expect(center.z).toBeCloseTo(5, 6);
  });
});

