export function buildLineup() {
  const g = new THREE.Group();
  for (let i = 0; i < 3; i++) {
    const car = new THREE.Mesh(new THREE.BoxGeometry(4, 1.4, 2));
    car.position.set(i * 10, 0.7, 0);
    g.add(car);
  }
  return g;
}

export function measureLineup(group) {
  // Box3.setFromObject reads each object's matrixWorld. Outside a render
  // loop nothing ever updates those matrices, and setFromObject only calls
  // updateWorldMatrix(false, false) per node — which never refreshes
  // ancestors — so boxes collapse toward stale (identity) parent transforms.
  // Update the whole subtree's world matrices before measuring.
  group.updateMatrixWorld(true);

  const box = new THREE.Box3();
  for (const child of group.children) {
    const b = new THREE.Box3().setFromObject(child);
    box.union(b);
  }
  return box;
}
